-- Resolve plan checks inside private helpers, so student policies do not depend on staff-only test SELECT policies.
create or replace function private.schoolpro_cbt_test_plan_allowed(p_test uuid)
returns boolean language sql stable security definer set search_path='' as $$
 select coalesce(private.is_active_account(),false) and exists(select 1 from public.schoolpro_cbt_tests t where t.id=p_test and (private.schoolpro_plan_feature_allowed(t.school_id,'cbt') or private.schoolpro_module_allowed(t.school_id,'cbt')))
$$;
create or replace function private.schoolpro_cbt_answer_plan_allowed(p_attempt uuid)
returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.schoolpro_cbt_attempts a where a.id=p_attempt and private.schoolpro_cbt_test_plan_allowed(a.test_id))
$$;
revoke all on function private.schoolpro_cbt_test_plan_allowed(uuid),private.schoolpro_cbt_answer_plan_allowed(uuid) from public;
grant execute on function private.schoolpro_cbt_test_plan_allowed(uuid),private.schoolpro_cbt_answer_plan_allowed(uuid) to authenticated;
alter policy schoolpro_plan_attempts on public.schoolpro_cbt_attempts using (private.schoolpro_cbt_test_plan_allowed(test_id)) with check (private.schoolpro_cbt_test_plan_allowed(test_id));
alter policy schoolpro_plan_answers on public.schoolpro_cbt_answers using (private.schoolpro_cbt_answer_plan_allowed(attempt_id)) with check (private.schoolpro_cbt_answer_plan_allowed(attempt_id));

alter table public.schoolpro_demo_requests
 add column if not exists term_start date,
 add column if not exists term_end date,
 add column if not exists exam_start date,
 add column if not exists exam_end date,
 add column if not exists calendar_path text,
 add column if not exists letter_path text,
 add column if not exists reviewed_by uuid references auth.users(id),
 add column if not exists reviewed_at timestamptz,
 add column if not exists review_reason text;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
values('schoolpro-demo-documents','schoolpro-demo-documents',false,10485760,array['application/pdf','image/jpeg','image/png']) on conflict(id) do nothing;
create policy schoolpro_demo_document_upload on storage.objects for insert to authenticated
with check(bucket_id='schoolpro-demo-documents' and (storage.foldername(name))[1]=auth.uid()::text and coalesce(private.is_active_account(),false));
create policy schoolpro_demo_document_read on storage.objects for select to authenticated
using(bucket_id='schoolpro-demo-documents' and coalesce(private.is_active_account(),false) and ((storage.foldername(name))[1]=auth.uid()::text or coalesce(private.has_product_access('schoolpro','approve'),false)));
create or replace function public.submit_schoolpro_term_demo(p_request uuid,p_tier text,p_term_start date,p_term_end date,p_exam_start date,p_exam_end date,p_calendar text,p_letter text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare result jsonb; did uuid;begin
 if auth.uid() is null or not coalesce(private.is_active_account(),false) then raise exception 'Active account required';end if;
 if p_term_start is null or p_term_end is null or p_exam_start is null or p_exam_end is null or p_term_end<(p_term_start+interval '3 months')::date or p_exam_start<p_term_start or p_exam_end<p_exam_start or p_exam_end>p_term_end or p_term_end<current_date then raise exception 'Submit a current term of at least three months with exams inside the term';end if;
 if p_calendar is null or p_letter is null or p_calendar=p_letter or split_part(p_calendar,'/',1)<>auth.uid()::text or split_part(p_letter,'/',1)<>auth.uid()::text or not exists(select 1 from storage.objects where bucket_id='schoolpro-demo-documents' and name=p_calendar) or not exists(select 1 from storage.objects where bucket_id='schoolpro-demo-documents' and name=p_letter) then raise exception 'Upload your calendar and request letter';end if;
 result:=public.request_schoolpro_workspace_demo(p_request,p_tier);did:=(result->>'demo_request_id')::uuid;
 update public.schoolpro_demo_requests set term_start=p_term_start,term_end=p_term_end,exam_start=p_exam_start,exam_end=p_exam_end,calendar_path=p_calendar,letter_path=p_letter,updated_at=now() where id=did and user_id=auth.uid() and activated_at is null and status='new';
 if not found then raise exception 'An activated demo cannot be changed';end if;
 return result||jsonb_build_object('status','awaiting_calendar_review');end $$;
revoke all on function public.submit_schoolpro_term_demo(uuid,text,date,date,date,date,text,text) from public,anon;
grant execute on function public.submit_schoolpro_term_demo(uuid,text,date,date,date,date,text,text) to authenticated,service_role;
create or replace function public.activate_schoolpro_demo(p_school uuid,p_tier text,p_days integer,p_reason text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare d public.schoolpro_demo_requests%rowtype; finish timestamptz; result jsonb;begin
 if auth.uid() is null or not coalesce(private.is_active_account(),false) or not coalesce(private.has_product_access('schoolpro','approve'),false) then raise exception 'Authorized school administrator required';end if;
 if length(trim(coalesce(p_reason,'')))<3 then raise exception 'Calendar review reason required';end if;
 perform 1 from public.schoolpro_schools where id=p_school for update;if not found then raise exception 'School unavailable';end if;
 if exists(select 1 from public.schoolpro_demo_requests where school_id=p_school and activated_at is not null) then raise exception 'This school has already used its demo';end if;
 if exists(select 1 from public.schoolpro_subscriptions where school_id=p_school and status='active' and amount>0 and renews_at>now()) then raise exception 'Paid subscription cannot be replaced by a demo';end if;
 select * into d from public.schoolpro_demo_requests where school_id=p_school and status='new' order by created_at desc limit 1 for update;
 if d.id is null or d.term_start is null or d.term_end is null or d.exam_start is null or d.exam_end is null or d.term_end<(d.term_start+interval '3 months')::date or d.exam_start<d.term_start or d.exam_end<d.exam_start or d.exam_end>d.term_end or d.calendar_path is null or d.letter_path is null then raise exception 'A complete term calendar and request letter are required';end if;
 if not exists(select 1 from storage.objects where bucket_id='schoolpro-demo-documents' and name=d.calendar_path and split_part(name,'/',1)=d.user_id::text) or not exists(select 1 from storage.objects where bucket_id='schoolpro-demo-documents' and name=d.letter_path and split_part(name,'/',1)=d.user_id::text) then raise exception 'Review documents unavailable';end if;
 finish:=greatest((d.term_end+1)::timestamp at time zone 'Africa/Lagos',(d.exam_end+15)::timestamp at time zone 'Africa/Lagos');
 if finish<=now() then raise exception 'Submitted demo term has ended';end if;
 result:=public.control_center_activate_schoolpro(p_school,p_tier,p_reason);
 update public.schoolpro_subscriptions set amount=0,billing_cycle='termly',starts_at=d.term_start::timestamp at time zone 'Africa/Lagos',renews_at=finish,updated_at=now() where school_id=p_school;
 update public.schoolpro_onboarding_requests set status='active',updated_at=now() where school_id=p_school;
 update public.schoolpro_demo_requests set status='completed',activated_at=now(),free_access_ends_at=finish,reviewed_by=auth.uid(),reviewed_at=now(),review_reason=trim(p_reason),updated_at=now() where id=d.id;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata) values(auth.uid(),'schoolpro_calendar_demo_approved','schoolpro','schoolpro_school',p_school::text,jsonb_build_object('demo_request_id',d.id,'term_end',d.term_end,'exam_end',d.exam_end,'access_ends_at',finish,'payment_recorded',false));
 return result||jsonb_build_object('source','calendar_demo','renews_at',finish);end $$;
create or replace function public.activate_schoolpro_demo(p_request uuid,p_school uuid)
returns jsonb language plpgsql security definer set search_path='' as $$ begin raise exception 'Use calendar-reviewed term demo approval';end $$;
-- Owners submit through the validated RPC, not a client-supplied activation record.
drop policy if exists "Users create demo requests" on public.schoolpro_demo_requests;

create or replace function public.submit_schoolpro_term_demo(p_request uuid,p_tier text,p_term_start date,p_term_end date,p_exam_start date,p_exam_end date,p_calendar text,p_letter text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare result jsonb; did uuid;begin
 if auth.uid() is null or not coalesce(private.is_active_account(),false) then raise exception 'Active account required';end if;
 if p_term_start is null or p_term_end is null or p_exam_start is null or p_exam_end is null or p_term_end<(p_term_start+interval '3 months')::date or p_exam_start<p_term_start or p_exam_end<p_exam_start or p_exam_end>p_term_end or p_term_end<current_date then raise exception 'Submit a current term of at least three months with exams inside the term';end if;
 if p_calendar is null or p_letter is null or p_calendar=p_letter or split_part(p_calendar,'/',1)<>auth.uid()::text or split_part(p_letter,'/',1)<>auth.uid()::text or not exists(select 1 from storage.objects where bucket_id='schoolpro-demo-documents' and name=p_calendar) or not exists(select 1 from storage.objects where bucket_id='schoolpro-demo-documents' and name=p_letter) then raise exception 'Upload your calendar and request letter';end if;
 result:=public.request_schoolpro_workspace_demo(p_request,p_tier);did:=(result->>'demo_request_id')::uuid;
 update public.schoolpro_demo_requests set term_start=p_term_start,term_end=p_term_end,exam_start=p_exam_start,exam_end=p_exam_end,calendar_path=p_calendar,letter_path=p_letter,updated_at=now() where id=did and user_id=auth.uid() and activated_at is null and status='new' and calendar_path is null;
 if not found then raise exception 'A submitted or activated demo cannot be changed';end if;
 return result||jsonb_build_object('status','awaiting_calendar_review');end $$;

create table if not exists public.datasub_network_availability (
 provider_id uuid not null references public.datasub_providers(id), service_type text not null,
 network text not null, available boolean not null, evidence_source text not null,
 checked_at timestamptz not null default now(), primary key(provider_id,service_type,network)
);
alter table public.datasub_network_availability enable row level security;
revoke all on public.datasub_network_availability from anon,authenticated;
grant all on public.datasub_network_availability to service_role;
insert into public.datasub_network_availability(provider_id,service_type,network,available,evidence_source)
select id,'DATA','MTN',false,'Provider dashboard network unavailable, verified 2026-10-08'
from public.datasub_providers where code in ('datastation','cashsub','legitdataway')
on conflict(provider_id,service_type,network) do update set available=false,evidence_source=excluded.evidence_source,checked_at=now();
create or replace function private.refresh_datasub_service_availability() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 insert into public.datasub_catalog_availability(offering_id,provider_available,healthy_route_count,updated_at)
 select o.id,count(r.id)>0,count(r.id)::integer,now()
 from public.datasub_catalog_offerings o
 left join (select r.id,r.offering_id from public.datasub_catalog_routes r
  join public.datasub_upstream_catalog u on u.id=r.upstream_catalog_id
  join public.datasub_providers p on p.id=u.provider_id
  join public.datasub_provider_health h on h.provider_id=p.id
  left join public.datasub_network_availability a on a.provider_id=p.id and a.service_type=upper(u.service_type) and a.network=upper(u.network)
  where r.route_enabled and u.active and p.is_active and h.state in ('HEALTHY','DEGRADED') and coalesce(a.available,true)
 ) r on r.offering_id=o.id
 group by o.id
 on conflict(offering_id) do update set provider_available=excluded.provider_available,healthy_route_count=excluded.healthy_route_count,updated_at=excluded.updated_at;
 return null;
end $$;
revoke all on function private.refresh_datasub_service_availability() from public,anon,authenticated;
create trigger datasub_network_availability_refresh after insert or update or delete on public.datasub_network_availability for each statement execute function private.refresh_datasub_service_availability();
create trigger datasub_route_availability_refresh after insert or update or delete on public.datasub_catalog_routes for each statement execute function private.refresh_datasub_service_availability();
create trigger datasub_upstream_availability_refresh after insert or update or delete on public.datasub_upstream_catalog for each statement execute function private.refresh_datasub_service_availability();
create trigger datasub_provider_availability_refresh after insert or update or delete on public.datasub_providers for each statement execute function private.refresh_datasub_service_availability();
create trigger datasub_health_availability_refresh after insert or update or delete on public.datasub_provider_health for each statement execute function private.refresh_datasub_service_availability();
update public.datasub_network_availability set checked_at=checked_at;

create or replace function private.datasub_attempt_network_availability() returns trigger
language plpgsql security definer set search_path='' as $$
declare t public.datasub_transactions; message text; network_name text;begin
 if new.response_status<>'FAILED' or new.is_ambiguous or nullif(new.provider_reference,'') is not null then return new;end if;
 message:=lower(coalesce(new.safe_response::text,''));
 if message not like '%data not available on this network currently%' and message not like '%mtn%currently not available%' then return new;end if;
 select * into t from public.datasub_transactions where id=new.transaction_id;
 select upper(network) into network_name from public.datasub_catalog_offerings where id=t.catalog_offering_id;
 if t.id is null or lower(t.service_type)<>'data' or network_name not in ('MTN','AIRTEL','GLO','T2','9MOBILE','VITEL') then return new;end if;
 insert into public.datasub_network_availability(provider_id,service_type,network,available,evidence_source)
 values(new.provider_id,'DATA',network_name,false,'Explicit provider network-unavailable response')
 on conflict(provider_id,service_type,network) do update set available=false,evidence_source=excluded.evidence_source,checked_at=now();
 return new;
end $$;
revoke all on function private.datasub_attempt_network_availability() from public,anon,authenticated;
create trigger datasub_attempt_network_availability after insert or update on public.datasub_provider_attempts for each row execute function private.datasub_attempt_network_availability();

create or replace function public.review_datasub_network_availability(p_provider uuid,p_service text,p_network text,p_available boolean,p_evidence text)
returns jsonb language plpgsql security definer set search_path='' as $$
begin
 if auth.uid() is null or not coalesce(private.is_active_account(),false) or not coalesce(private.has_product_access('datasub','approve'),false) then raise exception 'Administrator approval access required';end if;
 if p_available is null or length(trim(coalesce(p_evidence,'')))<10 then raise exception 'Confirmed availability and review evidence required';end if;
 if upper(p_service) not in ('DATA','AIRTIME','CABLE','ELECTRICITY','EXAM') or not exists(select 1 from public.datasub_upstream_catalog where provider_id=p_provider and upper(service_type)=upper(p_service) and upper(network)=upper(p_network)) then raise exception 'Service network not found';end if;
 insert into public.datasub_network_availability(provider_id,service_type,network,available,evidence_source)
 values(p_provider,upper(p_service),upper(p_network),p_available,trim(p_evidence))
 on conflict(provider_id,service_type,network) do update set available=excluded.available,evidence_source=excluded.evidence_source,checked_at=now();
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata) values(auth.uid(),'datasub_network_availability_review','datasub','datasub_provider',p_provider::text,jsonb_build_object('service',upper(p_service),'network',upper(p_network),'available',p_available,'evidence',trim(p_evidence)));
 return jsonb_build_object('available',p_available,'service',upper(p_service),'network',upper(p_network));
end $$;
revoke all on function public.review_datasub_network_availability(uuid,text,text,boolean,text) from public,anon;
grant execute on function public.review_datasub_network_availability(uuid,text,text,boolean,text) to authenticated;
grant select on public.datasub_network_availability to authenticated;
create policy datasub_network_availability_admin_read on public.datasub_network_availability for select to authenticated using(private.is_active_account() and private.has_product_access('datasub','approve'));

alter table public.schoolpro_assessment_schemes drop constraint schoolpro_assessment_schemes_school_level_check;
alter table public.schoolpro_assessment_schemes add constraint schoolpro_assessment_schemes_school_level_check check (school_level in ('nursery_primary','nursery','primary','secondary','junior_secondary','senior_secondary','custom','all'));
-- Editable starter choices, not a mandated national grading scheme.
create or replace function private.seed_schoolpro_report_defaults(p_school uuid)
returns void language plpgsql security definer set search_path='' as $$
declare preset record; components jsonb:='[{"key":"assignment_1","label":"1st CA Assignment","maxScore":10},{"key":"assignment_2","label":"2nd CA Assignment","maxScore":10},{"key":"test_1","label":"1st CA Test","maxScore":10},{"key":"test_2","label":"2nd CA Test","maxScore":10},{"key":"exam","label":"Examination","maxScore":60}]';
begin
 if not private.schoolpro_operationally_active(p_school) then return;end if;
 for preset in select * from (values ('Nursery Standard','nursery'),('Primary Standard','primary'),('Junior Secondary Standard','junior_secondary'),('Senior Secondary Standard','senior_secondary')) v(name,level) loop
  insert into public.schoolpro_assessment_schemes(school_id,name,school_level,components,is_default)
  values(p_school,preset.name,preset.level,components,preset.level='primary' and not exists(select 1 from public.schoolpro_assessment_schemes where school_id=p_school and is_default)) on conflict(school_id,name) do nothing;
 end loop;
 insert into public.schoolpro_result_domain_definitions(school_id,domain_type,name,position,is_active)
 select p_school,d.kind,d.name,d.position,true from (values
 ('affective','Punctuality',1),('affective','Attendance',2),('affective','Honesty',3),('affective','Cooperation',4),('affective','Neatness',5),('affective','Politeness',6),('affective','Self-control',7),('affective','Responsibility',8),
 ('psychomotor','Handwriting',1),('psychomotor','Reading',2),('psychomotor','Verbal communication',3),('psychomotor','Drawing',4),('psychomotor','Practical work',5),('psychomotor','Sports',6),('psychomotor','Music',7),('psychomotor','Creativity',8)) d(kind,name,position)
 where not exists(select 1 from public.schoolpro_result_domain_definitions old where old.school_id=p_school and old.domain_type=d.kind);
 if not exists(select 1 from public.schoolpro_result_rating_scale where school_id=p_school) then
  insert into public.schoolpro_result_rating_scale(school_id,rating,description,position) values(p_school,5,'Excellent',1),(p_school,4,'Very good',2),(p_school,3,'Good',3),(p_school,2,'Fair',4),(p_school,1,'Needs improvement',5);
 end if;
end $$;
revoke all on function private.seed_schoolpro_report_defaults(uuid) from public,anon,authenticated;
create or replace function private.create_default_school_assessment_scheme()
returns trigger language plpgsql security definer set search_path='' as $$ begin perform private.seed_schoolpro_report_defaults(new.id);return new;end $$;
revoke all on function private.create_default_school_assessment_scheme() from public,anon,authenticated;
do $$ declare s record;begin for s in select id from public.schoolpro_schools loop perform private.seed_schoolpro_report_defaults(s.id);end loop;end $$;

-- Reuse the printable-result authorization and outstanding-fee gate.
create or replace function private.schoolpro_report_details(p_student uuid,p_term text,p_session text)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare s public.schoolpro_students; ts public.schoolpro_result_term_settings; count_results integer; result jsonb;
begin
 if auth.uid() is null then raise exception 'Authentication required';end if;
 select count(*) into count_results from public.schoolpro_printable_result(p_student,p_term,p_session);
 if count_results=0 then raise exception 'No published results available';end if;
 select * into s from public.schoolpro_students where id=p_student;
 select * into ts from public.schoolpro_result_term_settings where school_id=s.school_id and term=trim(p_term) and session=trim(p_session);
 select jsonb_build_object(
 'settings',to_jsonb(ts),'gender',s.gender,'date_of_birth',s.date_of_birth,'photo_storage_path',s.photo_storage_path,
 'domains',coalesce((select jsonb_agg(jsonb_build_object('type',d.domain_type,'name',d.name,'rating',r.rating) order by d.domain_type,d.position) from public.schoolpro_result_domain_definitions d left join public.schoolpro_result_domain_ratings r on r.definition_id=d.id and r.school_id=s.school_id and r.student_id=s.id and r.term=trim(p_term) and r.session=trim(p_session) where d.school_id=s.school_id and d.is_active),'[]'::jsonb),
 'rating_scale',coalesce((select jsonb_agg(jsonb_build_object('rating',rating,'description',description) order by position) from public.schoolpro_result_rating_scale where school_id=s.school_id),'[]'::jsonb),
 'grade_scale',coalesce((select jsonb_agg(jsonb_build_object('label',label,'min_score',min_score,'max_score',max_score,'remark',remark,'overall_remark',overall_remark) order by position) from public.schoolpro_grade_scale where school_id=s.school_id and is_active),'[]'::jsonb),
 'attendance',case when ts.term_start_date is not null and ts.term_end_date is not null then (select jsonb_build_object('present',count(*) filter(where status::text='present'),'absent',count(*) filter(where status::text='absent'),'leave',count(*) filter(where status::text in ('leave','excused')),'recorded',count(*)) from public.schoolpro_attendance where student_id=s.id and attendance_date between ts.term_start_date and ts.term_end_date) else null end,
 'rank',(select to_jsonb(r) from public.schoolpro_result_class_rank(s.id,p_term,p_session) r limit 1),
 'logo_storage_path',(select logo_storage_path from public.schoolpro_result_templates where school_id=s.school_id limit 1)
 ) into result;return result;
end $$;
revoke all on function private.schoolpro_report_details(uuid,text,text) from public,anon;
grant execute on function private.schoolpro_report_details(uuid,text,text) to authenticated;
create or replace function public.schoolpro_report_details(p_student uuid,p_term text,p_session text)
returns jsonb language sql stable security invoker set search_path='' as $$ select private.schoolpro_report_details(p_student,p_term,p_session) $$;
revoke all on function public.schoolpro_report_details(uuid,text,text) from public,anon;
grant execute on function public.schoolpro_report_details(uuid,text,text) to authenticated;

create table public.datasub_pin_recovery_attempts (
  user_id uuid primary key references public.profiles(id) on delete cascade,
  window_started_at timestamptz not null default now(),
  attempts integer not null default 1 check (attempts between 1 and 6)
);
alter table public.datasub_pin_recovery_attempts enable row level security;
revoke all on public.datasub_pin_recovery_attempts from public, anon, authenticated;
grant all on public.datasub_pin_recovery_attempts to service_role;

create function public.claim_datasub_pin_recovery(p_user uuid) returns boolean
language plpgsql security invoker set search_path = '' as $$
declare count_used integer;
begin
  insert into public.datasub_pin_recovery_attempts as a(user_id) values(p_user)
  on conflict(user_id) do update set
    attempts = case when a.window_started_at <= now() - interval '15 minutes' then 1 else least(a.attempts + 1, 6) end,
    window_started_at = case when a.window_started_at <= now() - interval '15 minutes' then now() else a.window_started_at end
  returning attempts into count_used;
  return count_used <= 5;
end $$;

create function public.recover_datasub_transaction_pin(p_user uuid, p_pin text) returns void
language plpgsql security invoker set search_path = '' as $$
begin
  if p_pin is null or p_pin !~ '^[0-9]{4}$' then raise exception 'Invalid PIN'; end if;
  insert into public.datasub_transaction_pins(user_id,pin_hash,failed_attempts,locked_until,updated_at)
  values(p_user,extensions.crypt(p_pin,extensions.gen_salt('bf')),0,null,now())
  on conflict(user_id) do update set pin_hash=excluded.pin_hash,failed_attempts=0,locked_until=null,updated_at=now();
end $$;
revoke all on function public.claim_datasub_pin_recovery(uuid) from public, anon, authenticated;
revoke all on function public.recover_datasub_transaction_pin(uuid,text) from public, anon, authenticated;
grant execute on function public.claim_datasub_pin_recovery(uuid) to service_role;
grant execute on function public.recover_datasub_transaction_pin(uuid,text) to service_role;

create table public.schoolpro_initial_credentials(
 user_id uuid primary key references public.profiles(id) on delete cascade,
 school_id uuid not null references public.schoolpro_schools(id) on delete cascade,
 surname_hash text not null,
 expires_at timestamptz not null default now()+interval '7 days',
 consumed_at timestamptz
);
create table public.schoolpro_account_challenges(
 token_hash text primary key,
 user_id uuid not null references public.schoolpro_initial_credentials(user_id) on delete cascade,
 expires_at timestamptz not null default now()+interval '10 minutes'
);
create table public.schoolpro_access_invitations(
 id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schoolpro_schools(id) on delete cascade,
 email text not null, role text not null check(role in ('administrator','teacher','accountant','parent')),
 student_ids uuid[] not null default '{}', relationship text not null default 'guardian',
 token_hash text unique not null, created_by uuid not null references public.profiles(id),
 expires_at timestamptz not null default now()+interval '7 days', accepted_at timestamptz
);
