   where id = p_school_id;

  update public.schoolpro_leadership_settings
     set owner_title = 'Proprietor'
   where school_id = p_school_id;

  -- Remove the former owner's school membership only; their platform-level Super Admin role is untouched.
  delete from public.schoolpro_members
   where school_id = p_school_id and user_id = v_old_owner;

  return jsonb_build_object(
    'ok', true,
    'school_id', p_school_id,
    'new_owner_id', p_new_owner_id,
    'previous_owner_membership_removed', true,
    'platform_super_admin_role_unchanged', true
